from datetime import datetime

def process_timestamps(items):
    parsed_values = []
    failed_values = []
    for value in items:
        try:
            dt_obj = datetime.strptime(value, '%Y-%m-%d %H:%M:%S')
            parsed_values.append(dt_obj)
        except ValueError:
            pass
    return {'parsed': parsed_values, 'failed': failed_values}
